const tasks = [
  { name: 'Clean the windows', energy: 'High', minutes: 15 },
  { name: 'Deep scrub the shower & toilet', energy: 'High', minutes: 15 },
  { name: 'Mop the kitchen & living room floors', energy: 'High', minutes: 12 },
  { name: 'Vacuum the living and master bedroom carpets', energy: 'High', minutes: 12 },
  { name: 'Wipe down kitchen counters & induction stove', energy: 'Low', minutes: 5 },
  { name: 'Clean office', energy: 'Medium', minutes: 10 },
  { name: 'Empty all trash bins & take out recycling', energy: 'Low', minutes: 4 },
  { name: 'Dust the TV console and coffee table', energy: 'Low', minutes: 5 },
  { name: 'Wipe down bathroom mirror and sink', energy: 'Low', minutes: 4 },
  { name: 'Load and start the laundry machine', energy: 'Low', minutes: 6 }
];
const now = new Date();
const dayOfWeek = now.toLocaleDateString('en-US', { weekday: 'long' });
const dateStr = now.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
return [{ json: { dayOfWeek, date: dateStr, tasks } }];

// Guardrail: check the AI plan against the business rules; fall back to a rule-based plan if it fails
const MAX_MINUTES = 20;
const MAX_HIGH = 1;
const tasks = $('Master Task List').first().json.tasks;
const known = new Map(tasks.map(t => [t.name, t]));
const raw = String($input.first().json.output ?? '');
const issues = [];
let plan = null;

try {
  plan = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch (e) {
  issues.push('AI output was not valid JSON');
}

if (plan) {
  const selected = Array.isArray(plan.selected) ? plan.selected : [];
  if (!selected.length) issues.push('No chores selected');
  const unknown = selected.filter(t => !known.has(t.name));
  if (unknown.length) issues.push(`Unknown chore(s): ${unknown.map(t => t.name).join(', ')}`);
  // Re-derive time and energy from the master list instead of trusting the model's numbers
  const clean = selected.filter(t => known.has(t.name)).map(t => known.get(t.name));
  const total = clean.reduce((s, t) => s + t.minutes, 0);
  const highs = clean.filter(t => t.energy === 'High').length;
  if (total > MAX_MINUTES) issues.push(`Total time ${total} min exceeds ${MAX_MINUTES}`);
  if (highs > MAX_HIGH) issues.push(`${highs} high-energy chores (max ${MAX_HIGH})`);
  plan = { selected: clean, totalMinutes: total, reasoning: plan.reasoning ?? '' };
}

if (issues.length) {
  // Deterministic fallback: rotate the list by weekday and fill greedily within the rules
  const offset = new Date().getDay();
  const rotated = tasks.map((_, i) => tasks[(i + offset) % tasks.length]);
  const selected = [];
  let total = 0, highs = 0;
  for (const t of rotated) {
    if (t.energy === 'High' && highs >= MAX_HIGH) continue;
    if (total + t.minutes > MAX_MINUTES) continue;
    selected.push(t);
    total += t.minutes;
    if (t.energy === 'High') highs++;
  }
  plan = { selected, totalMinutes: total, reasoning: 'Backup plan used (AI plan failed checks: ' + issues.join('; ') + ').' };
}

return [{ json: { ...plan, validation: { passed: issues.length === 0, issues } } }];

